const props=defineProps({asOf:String,arRows:Array,apRows:Array,totals:Object,currency:Object,urls:Object})
const form=reactive({as_of:props.asOf});const money=(v)=>`${new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))} ${props.currency.symbol}`;const visit=()=>router.get(props.urls.index,form,{preserveState:true,preserveScroll:true})
